import{_ as a,c as t,o as s,a3 as r}from"./chunks/framework.Dokpd4od.js";const p=JSON.parse('{"title":"Candidates","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/recruitment/applicants/candidates.md","filePath":"master/human-resources/recruitment/applicants/candidates.md","lastUpdated":1791902625000}'),i={name:"master/human-resources/recruitment/applicants/candidates.md"};function o(n,e,l,d,c,h){return s(),t("div",null,e[0]||(e[0]=[r('<h1 id="candidates" tabindex="-1">Candidates <a class="header-anchor" href="#candidates" aria-label="Permalink to &quot;Candidates&quot;">​</a></h1><p>A candidate is a person in your talent pool. It holds their name, contact details, degree, tags and skills once. Each time the person applies for a job, Aureus creates an applicant linked to the candidate. Because of this, you never retype details when someone applies twice.</p><blockquote><p><strong>In simple words:</strong> The candidate is the person. Create it once and reuse it for every application.</p></blockquote><p>Open <code>Recruitments → Applications → Candidates</code>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The page lists candidates as cards. Use <strong>Sort by</strong> to order them by <strong>Full Name</strong>. Group them by <strong>Manager</strong>. Each card has <strong>View</strong>, <strong>Edit</strong> and <strong>Delete</strong>.</p><h2 id="create-a-candidate" tabindex="-1">Create a candidate <a class="header-anchor" href="#create-a-candidate" aria-label="Permalink to &quot;Create a candidate&quot;">​</a></h2><p>You can also create a candidate while <a href="./add-applicant.html">adding an applicant</a>.</p><ol><li>Click <strong>New Candidate</strong>. The page is titled <strong>Create Candidate</strong>.</li></ol><h3 id="basic-information" tabindex="-1">Basic Information <a class="header-anchor" href="#basic-information" aria-label="Permalink to &quot;Basic Information&quot;">​</a></h3><ol start="2"><li>Fill in the person&#39;s details.</li></ol><ul><li><strong><em>Full Name:</em></strong> Required. Example: <code>Rahul Verma</code>.</li><li><strong><em>Email Address:</em></strong> The email used for messages. Example: <code>rahul.verma@example.com</code>.</li><li><strong><em>Phone Number:</em></strong> The contact number.</li><li><strong><em>LinkedIn Profile:</em></strong> The link to the person&#39;s profile.</li></ul><h3 id="additional-details" tabindex="-1">Additional Details <a class="header-anchor" href="#additional-details" aria-label="Permalink to &quot;Additional Details&quot;">​</a></h3><ol start="3"><li>Add the rest if you know it.</li></ol><ul><li><strong><em>Degree:</em></strong> The highest degree. Create options in <a href="./../setup/tags-degrees.html">Tags and degrees</a>.</li><li><strong><em>Tags:</em></strong> Labels that describe the person.</li><li><strong><em>Manager:</em></strong> The user who looks after this candidate.</li><li><strong><em>Availability Date:</em></strong> When the person can start.</li><li><strong><em>Status:</em></strong> A toggle for an active candidate.</li><li><strong><em>Evaluation:</em></strong> A star rating.</li></ul><ol start="4"><li>Click <strong>Create</strong>, or <strong>Create &amp; create another</strong> to add more.</li></ol><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><p>Open a candidate and use the <strong>Skills</strong> table, or the <strong>Manage Skills</strong> tab. Click <strong>Add Skill</strong> to record a skill. Each row shows <strong>Skill Type</strong>, <strong>Skill</strong>, <strong>Skill Level</strong> and <strong>Level Percent</strong>. Use the row actions to view, edit or delete a skill. Skill types are set up in the employee settings.</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><ul><li><strong>Create employee:</strong> on the candidate page, turns the person into an employee.</li><li><strong>Delete:</strong> removes the candidate.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./add-applicant.html">Add an applicant</a></li><li><a href="./process-applicant.html">Process an applicant</a></li><li><a href="./../../employees/employees/skills-and-resume.html">Skills and resume</a></li></ul>',22)]))}const g=a(i,[["render",o]]);export{p as __pageData,g as default};
